import collections
import pandas as pd
from typing import List, Dict, Any
def task_func(my_tuple: tuple, path_csv_files: List[str]) -> Dict[str, Dict[Any, int]]:
    """
    Count the occurrences of each value in the specified columns in multiple CSV files.

    Args:
    my_tuple: A tuple containing the column names to analyze.
    path_csv_files: A list of file paths to the CSV files.

    Returns:
    A dictionary where keys are column names and values are dictionaries
    with unique values in the column as keys and their counts as values.
    """
    result = {column: collections.defaultdict(int) for column in my_tuple}

    for file_path in path_csv_files:
        df = pd.read_csv(file_path)
        for column in my_tuple:
            if column in df.columns:
                for value in df[column]:
                    result[column][value] += 1

    return {column: dict(counts) for column, counts in result.items()}

