import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    try:
        # Make a request to the API
        with urllib.request.urlopen(API_URL) as response:
            # Read the response
            data = response.read().decode('utf-8')

            # Try to parse the response as JSON
            try:
                json_data = json.loads(data)
                # Check if the IP address is in the JSON response
                if 'ip' in json_data:
                    ip_address = json_data['ip']
                    # Validate the IP address format
                    if re.match(IP_REGEX, ip_address):
                        return ip_address
                    else:
                        raise ValueError("Invalid IP address format")
                else:
                    raise KeyError("IP address not found in JSON response")
            except json.JSONDecodeError:
                # If JSON parsing fails, try to find the IP address using regex
                match = re.search(IP_REGEX, data)
                if match:
                    return match.group(0)
                else:
                    raise ValueError("IP address not found in response")
    except urllib.error.URLError as e:
        # Handle URL errors
        raise Exception(f"API request failed: {e.reason}")
    except urllib.error.HTTPError as e:
        # Handle HTTP errors
        raise Exception(f"API request failed: {e.code} {e.reason}")

