def task_func(directory, string):
    def search_in_json(data, target):
        if isinstance(data, dict):
            for key, value in data.items():
                if search_in_json(value, target):
                    return True
        elif isinstance(data, list):
            for item in data:
                if search_in_json(item, target):
                    return True
        elif isinstance(data, str):
            return data == target
        return False

