        success = False
        failed_files.append(e.stderr.decode('utf-8'))
    except Exception as e:
        success = False
        failed_files.append(str(e))
    return {
        'success': success,
        'message': 'Files compressed and moved successfully' if success else 'Failed to compress or move files',
        'failed_files': failed_files
    }
