import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        return {'CPU Usage': 0, 'Memory Usage': 0}

    start_time = time.time()
    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

    try:
        while True:
            if process.poll() is not None:
                break
            time.sleep(0.1)

            cpu_usage = process.cpu_percent(interval=1)
            memory_usage = process.memory_info().rss

            if time.time() - start_time > timeout:
                break

            print(f"CPU Usage: {cpu_usage}% | Memory Usage: {memory_usage} bytes")
    except subprocess.TimeoutExpired:
        print(f"Script execution timed out after {timeout} seconds.")
        process.terminate()

    process.wait()

    if process.returncode == 0:
        cpu_usage = process.cpu_percent(interval=1)
        memory_usage = process.memory_info().rss
    else:
        cpu_usage = 0
        memory_usage = 0

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

