import string
def task_func(length: int, predicates: list, seed: int = None):
    if length < 0:
        raise ValueError("Length must be non-negative")

    if seed is not None:
        random.seed(seed)

    # Define the set of characters to use
    chars = string.ascii_letters + string.digits + string.punctuation

    # Generate the random text
    text = ''.join(random.choice(chars) for _ in range(length))

    # Evaluate the text for the specified predicates
    characteristics = {}
    for predicate in predicates:
        if predicate == 'uppercase':
            characteristics['uppercase'] = any(char.isupper() for char in text)
        elif predicate == 'lowercase':
            characteristics['lowercase'] = any(char.islower() for char in text)
        elif predicate == 'digit':
            characteristics['digit'] = any(char.isdigit() for char in text)
        elif predicate == 'punctuation':
            characteristics['punctuation'] = any(char in string.punctuation for char in text)
        else:
            raise KeyError(f"Unrecognized predicate: {predicate}")

    return text, characteristics

