import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        # Send HTTP GET request with a 5-second timeout
        response = requests.get(url, timeout=5)
        response.raise_for_status()  # Raise an exception for HTTP errors

        # Decode the response content using chardet to detect the encoding
        detected_encoding = chardet.detect(response.content)['encoding']

        # If no encoding is detected, return an empty dictionary
        if detected_encoding is None:
            return {}

        # Decode the response content using the detected encoding
        decoded_content = response.content.decode(detected_encoding)

        # Re-encode the decoded content to the specified encoding
        reencoded_content = decoded_content.encode(to_encoding)

        # Parse the re-encoded content as JSON
        json_data = json.loads(reencoded_content)

        return json_data
    except requests.exceptions.RequestException as e:
        print(f"Error fetching data: {e}")
        return {}
    except ValueError as e:
        print(f"Unable to detect encoding for non-empty content: {e}")
        return {}
    except json.JSONDecodeError as e:
        print(f"Error parsing JSON: {e}")
        return {}

