import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Both interval and duration must be greater than zero.")

    if platform.system() == "Windows":
        command = f"wmic cpu get loadpercentage /value"
    elif platform.system() == "Linux":
        command = "top -bn1 | grep Cpu | awk '{print $2}'"
    else:
        raise ValueError("Unsupported platform. Only Windows and Linux are supported.")

    with open(LOGFILE_PATH, 'w') as log_file:
        try:
            start_time = time.time()
            while time.time() - start_time < duration:
                output = subprocess.check_output(command, shell=True, text=True)
                cpu_usage = float(output.split('=')[1].strip())
                log_file.write(f"{time.time()}: {cpu_usage}\n")
                time.sleep(interval)
            return LOGFILE_PATH
        except subprocess.CalledProcessError as e:
            print(f"Error occurred: {e}")
            return None

