from glob import glob
def task_func(src_folder, dst_folder):
    # Check if source folder exists
    if not os.path.exists(src_folder):
        return {'success': False, 'message': f'Source folder {src_folder} does not exist.', 'failed_files': []}

    # Check if destination folder exists
    if not os.path.exists(dst_folder):
        return {'success': False, 'message': f'Destination folder {dst_folder} does not exist.', 'failed_files': []}

    # Get all files in the source folder
    files = glob(os.path.join(src_folder, '*'))

    failed_files = []
    for file in files:
        # Check if the file is a regular file
        if os.path.isfile(file):
            # Compress the file
            compressed_file = file + '.gz'
            subprocess.run(['gzip', '-c', file, '-o', compressed_file])

            # Check if the file was compressed successfully
            if os.path.exists(compressed_file):
                # Move the compressed file to the destination folder
                shutil.move(compressed_file, dst_folder)
            else:
                failed_files.append(file)
        else:
            failed_files.append(file)

    # Check if all files were compressed and moved successfully
    if not failed_files:
        return {'success': True, 'message': 'All files were compressed and moved successfully.', 'failed_files': []}
    else:
        return {'success': False, 'message': 'Some files failed to compress or move.', 'failed_files': failed_files}

