import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        return {'Error': 'Script not found'}

    start_time = time.time()
    cpu_usage = 0.0
    memory_usage = 0

    while True:
        try:
            process = subprocess.run(["bash", script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout)
        except subprocess.TimeoutExpired:
            return {'Error': 'Script timed out'}
        except FileNotFoundError:
            return {'Error': 'Script not found'}

        cpu_percent = process.cpu_percent(interval=1)
        memory_info = psutil.virtual_memory()
        memory_usage += memory_info.rss

        cpu_usage += cpu_percent

        if process.returncode != 0:
            return {'Error': 'Script failed with exit code ' + str(process.returncode)}

        if time.time() - start_time > timeout:
            break

    cpu_usage /= timeout
    memory_usage /= (1024 * 1024)  # Convert bytes to MB

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

