def task_func(x):
    # Initialize minimum length to a large number
    min_length = math.inf
    min_subsequence = None

    # Iterate over all possible subsequences
    for length in range(1, len(x) + 1):
        for subsequence in itertools.combinations(x, length):
            # Calculate the total length of the subsequence
            total_length = sum(x[key] for key in subsequence)
