import math
def task_func(numbers):
    if not isinstance(numbers, list):
        raise TypeError("Input should be a list of integers")
    if any(i < 0 for i in numbers):
        raise ValueError("Input numbers should be non-negative")
    if not numbers:
        return []

    def factorial(n):
        if n == 0:
            return 1
        else:
            return n * factorial(n-1)

    def sum_of_factorials(numbers):
        return [factorial(i) for i in numbers]

    permutations_list = list(permutations(numbers))

    return sum_of_factorials(numbers), permutations_list

