from itertools import zip_longest
from scipy.spatial import distance
def task_func(points):
    if not points or len(points) == 1:
        return []

    distances = []
    for point1, point2 in zip_longest(points, points[1:]):
        if point1 is None or point2 is None:
            continue
        if isinstance(point1, tuple) and len(point1) == 1:
            point1 = (point1[0], point1[0])
        if isinstance(point2, tuple) and len(point2) == 1:
            point2 = (point2[0], point2[0])
        distances.append(distance.euclidean(point1, point2))

    return distances

