import re
from datetime import time
def task_func(logs: list):
    error_times = []
    for log in logs:
        match = re.search(r'ERROR at (\d+:\d+:\d+)', log)
        if match:
            error_times.append(time(int(match.group(1).split(':')[0]), int(match.group(1).split(':')[1]), int(match.group(1).split(':')[2])))

    if not error_times:
        return "No errors found"

    return error_times, sum(error_times, time()) / len(error_times)

