from typing import List, Union
import numpy as np
import scipy.fft
def task_func(data: List[Union[int, str]], repetitions: int = 1) -> dict:
    if not data or repetitions <= 0:
        return {'mode': [], 'count': []}

    data = np.array(data)
    repetitions = np.array(repetitions * [repetitions])
    data_repeated = np.repeat(data, repetitions)

    _, counts = np.unique(data_repeated, return_counts=True)
    modes = np.array(np.where(counts == max(counts))[0])

    return {'mode': modes.tolist(), 'count': counts.tolist()}

