import os
import glob
from collections import Counter
def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.exists(directory):
        raise OSError("The specified directory does not exist.")

    file_list = glob.glob(os.path.join(directory, '*'))
    file_extensions = [os.path.splitext(i)[1] for i in file_list]
    counter = Counter(file_extensions)

    if keep_zero:
        for ext in extensions:
            if ext[1:] not in counter.keys():
                counter[ext[1:]] = 0

    return counter

