import os
import shutil
def task_func(path, delimiter="/"):
    if not isinstance(path, str):
        raise ValueError("The 'path' should be a string.")
    if not path:
        raise ValueError("The 'path' should not be empty.")
    if delimiter not in path:
        raise ValueError("The 'path' should contain the delimiter.")
    if not os.path.exists(path):
        raise FileNotFoundError("The 'path' does not exist in the filesystem.")

    components = path.split(delimiter)
    disk_usages = []
    for component in components:
        total, used, free = shutil.disk_usage(component)
        disk_usages.append((component, {'total': total.total // (1024 * 1024 * 1024), 'used': used.used // (1024 * 1024 * 1024), 'free': free.free // (1024 * 1024 * 1024)}))

    return disk_usages

