import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        # Fetch data from the specified REST API URL
        response = requests.get(url, timeout=5)

        # Check if the content is empty
        if not response.content:
            return {}

        # Detect the encoding of the content
        if from_encoding:
            detected_encoding = from_encoding
        else:
            detected_encoding = chardet.detect(response.content)['encoding']

        # Decode the content
        decoded_content = response.content.decode(detected_encoding)

        # Re-encode the content
        re_encoded_content = decoded_content.encode(to_encoding)

        # Parse the re-encoded content as JSON
        json_content = json.loads(re_encoded_content)

        return json_content

    except requests.exceptions.RequestException as e:
        # Handle exceptions
        print(f"An error occurred: {e}")
        return {}

    except ValueError as e:
        # Handle ValueError: "Unable to detect encoding for non-empty content"
        print(f"Unable to detect encoding for non-empty content: {e}")
        return {}

