import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {'success': False, 'message': f'Source folder {src_folder} does not exist.', 'failed_files': []}

    if not os.path.exists(dst_folder):
        return {'success': False, 'message': f'Destination folder {dst_folder} does not exist.', 'failed_files': []}

    failed_files = []
    all_files_processed = True
    for file in glob(os.path.join(src_folder, '*')):
        if os.path.isfile(file):
            try:
                # Compress the file using gzip
                subprocess.run(['gzip', file], check=True)

                # Move the compressed file to the destination folder
                shutil.move(file + '.gz', dst_folder)
            except Exception as e:
                all_files_processed = False
                failed_files.append(file)

    return {'success': all_files_processed, 'message': 'All files were compressed and moved successfully.' if all_files_processed else 'Some files failed to compress or move.', 'failed_files': failed_files}

