import re
import pandas as pd
def task_func(json_str):
    if not json_str:
        return pd.DataFrame()

    # Load JSON string into a dictionary
    data_dict = json.loads(json_str)

    # Normalize the dictionary by doubling the numerical values
    def normalize_value(value):
        if isinstance(value, (int, float)):
            return value * 2
        elif isinstance(value, str):
            # Extract numerical values from string
            numbers = re.findall(r'\d+\.?\d*', value)
            if numbers:
                # Convert extracted numbers to float and double them
                return [float(num) * 2 for num in numbers]
        elif isinstance(value, list):
            return [normalize_value(item) for item in value]
        return value

    data_dict = {key: normalize_value(value) for key, value in data_dict.items()}

    # Create a Pandas DataFrame from the dictionary
    df = pd.DataFrame(data_dict)

    return df

