import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"The script path {script_path} does not exist.")

    start_time = time.time()
    process = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    cpu_percent = 0.0
    memory_usage = 0.0

    while True:
        if time.time() - start_time > timeout:
            process.terminate()
            break

        if psutil.pid_exists(process.pid):
            process_info = psutil.Process(process.pid)
            cpu_percent += process_info.cpu_percent(interval=1)
            memory_usage += process_info.memory_info().rss
        else:
            break

    return {'CPU Usage': cpu_percent, 'Memory Usage': memory_usage}

