import pandas as pd
def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if not pattern:
        return df.copy()

    def reverse_words(match):
        return ' '.join(match.group(0).split(' ')[::-1])

    df_copy = df.copy()
    df_copy[column_name] = df_copy[column_name].apply(
        lambda x: re.sub(pattern, reverse_words, x)
    )
    return df_copy

