import time
BACKUP_DIR = '/tmp/backup'
def get_unique_backup_dir():
    return os.path.join(BACKUP_DIR, str(time.time()))
def task_func(directory):
    errors = []
    if not os.path.exists(directory):
        errors.append(f"Directory {directory} does not exist.")
        return (None, errors)

    backup_dir = get_unique_backup_dir()
    try:
        shutil.copytree(directory, backup_dir)
    except Exception as e:
        errors.append(f"Error during backup: {str(e)}")

    try:
        for filename in os.listdir(directory):
            file_path = os.path.join(directory, filename)
            try:
                if os.path.isfile(file_path) or os.path.islink(file_path):
                    os.unlink(file_path)
                elif os.path.isdir(file_path):
                    shutil.rmtree(file_path)
            except Exception as e:
                errors.append(f"Error while cleaning directory: {str(e)}")
    except Exception as e:
        errors.append(f"Error while cleaning directory: {str(e)}")

    return (backup_dir, errors)

