def task_func(data, file_path, headers):
    if file_path is None:
        raise ValueError("'file_path' cannot be None")

    with open(file_path, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(headers)
        for row in data:
            while len(row) < len(headers):
                row += (None,)
            writer.writerow(row)

    return os.path.abspath(file_path)

from itertools import tee, islice
from math import sqrt
def pairwise(iterable):
    a, b = tee(iterable, 2)
    return zip(a, islice(b, 1, None))
def task_func(points):
    if len(points) < 2:
        return []
    distances = []
    for point1, point2 in pairwise(points):
        x1, y1 = point1 if len(point1) == 2 else (point1[0], point1[0])
        x2, y2 = point2 if len(point2) == 2 else (point2[0], point2[0])
        distance = sqrt((x2 - x1)**2 + (y2 - y1)**2)
        distances.append(distance)
    return distances

