import re
from datetime import datetime
def task_func(logs: list):
    error_times = []
    for log in logs:
        if 'error' in log.lower():
            match = re.search(r'\d{2}:\d{2}:\d{2}', log)
            if match:
                error_time = datetime.strptime(match.group(), '%H:%M:%S')
                error_times.append(error_time)

    if not error_times:
        return {'list': [], 'time': 'No errors occurred'}

    avg_time = sum(error_times, datetime.min) / len(error_times)
    avg_time = avg_time.time()

    return {'list': [str(time) for time in error_times], 'time': str(avg_time)}
