import string
POSSIBLE_LETTERS = ['a', 'b', 'c']
def task_func(word):
    # Check if the input contains non-letter characters
    if not all(char.isalpha() for char in word):
        raise ValueError("Input contains non-letter characters")

    # If the word has fewer than 2 letters, return a list of empty strings
    if len(word) < 2:
        return [""] * len(POSSIBLE_LETTERS)

    # Generate a list of random pairs of adjacent letters from the word
    pairs = [word[i:i+2] for i in range(len(word) - 1)]

    # If the number of pairs is less than the length of POSSIBLE_LETTERS,
    # return a list of empty strings
    if len(pairs) < len(POSSIBLE_LETTERS):
        return [""] * len(POSSIBLE_LETTERS)

    # Randomly select pairs from the list of pairs
    random_pairs = random.sample(pairs, len(POSSIBLE_LETTERS))

    return random_pairs

