import os
import glob
from collections import Counter
def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.exists(directory):
        raise OSError("The specified directory does not exist.")

    counter = Counter()
    for extension in extensions:
        files = glob.glob(directory + '/**/*' + extension, recursive=True)
        counter.update(files)

    if not keep_zero:
        counter = Counter({k: v for k, v in counter.items() if v > 0})

    return counter

import os
import re
import shutil
def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    if not os.path.exists(target_directory):
        os.makedirs(target_directory)

    count = 0
    for file_name in os.listdir(source_directory):
        if re.search(pattern, file_name):
            shutil.move(os.path.join(source_directory, file_name), target_directory)
            count += 1
    return count

