import random
import string
def task_func(length: int, predicates: list, seed: int = None):
    if length < 0:
        raise ValueError("Length cannot be negative")
    if seed is not None:
        random.seed(seed)
    valid_predicates = ['digits', 'punctuation', 'ascii_lowercase', 'ascii_uppercase']
    for predicate in predicates:
        if predicate not in valid_predicates:
            raise KeyError(f"Predicate {predicate} not recognized")
    predicates = list(set(predicates))  # remove duplicates
    charset = ''.join([string.digits if 'digits' in predicates else '',
                       string.punctuation if 'punctuation' in predicates else '',
                       string.ascii_lowercase if 'ascii_lowercase' in predicates else '',
                       string.ascii_uppercase if 'ascii_uppercase' in predicates else ''])
    random_string = ''.join(random.choices(charset, k=length))
    characteristics = {}
    for predicate in predicates:
        if predicate == 'digits':
            characteristics[predicate] = any(c.isdigit() for c in random_string)
        elif predicate == 'punctuation':
            characteristics[predicate] = any(c in string.punctuation for c in random_string)
        elif predicate == 'ascii_lowercase':
            characteristics[predicate] = any(c.islower() for c in random_string)
        elif predicate == 'ascii_uppercase':
            characteristics[predicate] = any(c.isupper() for c in random_string)
    return random_string, characteristics

