import zipfile
import os
import urllib.error
def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    try:
        urllib.request.urlretrieve(url, save_path)
    except urllib.error.URLError as e:
        return f"URL Error: {str(e.reason)}"
    except Exception as e:
        return f"Unexpected Error: {str(e)}"

    try:
        with zipfile.ZipFile(save_path, 'r') as zip_ref:
            zip_ref.extractall(extract_path)
    except zipfile.BadZipFile as e:
        os.remove(save_path)
        return f"BadZipFile Error: {str(e)}"
    except Exception as e:
        os.remove(save_path)
        return f"Unexpected Error: {str(e)}"

    try:
        os.remove(save_path)
    except Exception as e:
        return f"File I/O Error: {str(e)}"

    return extract_path

import os
import requests
from zipfile import ZipFile, BadZipFile
def task_func(url, download_path="mnt/data/downloads/"):
    try:
        response = requests.get(url, stream=True)
        if response.status_code != 200:
            return "Error: Unable to download the file from the provided URL."
        content_type = response.headers.get('content-type')
        if 'application/zip' not in content_type:
            return "Error: The URL does not point to a ZIP file."
        zip_file_path = os.path.join(download_path, 'downloaded.zip')
        with open(zip_file_path, 'wb') as f:
            f.write(response.content)
        try:
            with ZipFile(zip_file_path, 'r') as zip_ref:
                zip_ref.extractall(download_path)
        except BadZipFile:
            return "Error: The downloaded file is not a valid ZIP file."
        except Exception as e:
            return f"Error: {str(e)}"
        return download_path
    except requests.exceptions.RequestException:
        return "Error: Unable to download the file from the provided URL."
    except Exception as e:
        return f"Error: {str(e)}"

