import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"The file {script_path} does not exist.")

    class InterruptableThread(threading.Thread):
        def __init__(self, *args, **kwargs):
            super(InterruptableThread, self).__init__(*args, **kwargs)
            self.result = None

        def run(self):
            self.result = subprocess.run(['python', script_path], capture_output=True, text=True)

    thread = InterruptableThread()
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        thread.result = None
        thread.join()
        return "Terminating process due to timeout."
    else:
        if thread.result.returncode != 0:
            print(thread.result.stderr)
        return "Script executed successfully."

