import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    # Check if source folder exists
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}

    # Check if destination folder exists, if not create it
    if not os.path.isdir(dst_folder):
        os.makedirs(dst_folder)

    # Get all files in the source folder
    files = glob(os.path.join(src_folder, '*'))

    failed_files = []
    for file in files:
        # Compress the file
        try:
            subprocess.check_call(['gzip', file])
        except subprocess.CalledProcessError:
            failed_files.append(file)
            continue

        # Move the compressed file to the destination folder
        try:
            shutil.move(file + '.gz', dst_folder)
        except shutil.Error:
            failed_files.append(file)
            continue

    # Check if all files were compressed and moved successfully
    if len(failed_files) == 0:
        return {'success': True, 'message': 'All files were compressed and moved successfully.', 'failed_files': []}
    else:
        return {'success': False, 'message': 'Some files failed to compress or move.', 'failed_files': failed_files}

