            # Update summary
            if "Invalid" in summary:
                summary["Invalid"] += 1
            else:
                summary["Invalid"] = 1
        else:
            # Get file ending
            ending = filename.split(".")[-1]

            # Create directory for file ending if it doesn't exist
            ending_dir = os.path.join(directory_path, ending)
            if not os.path.exists(ending_dir):
                os.makedirs(ending_dir)

            # Move file to directory for file ending
            shutil.move(os.path.join(directory_path, filename), ending_dir)

            # Update summary
            if ending in summary:
                summary[ending] += 1
            else:
                summary[ending] = 1

