def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {'mode': np.array([]), 'count': np.array([])}

    data = np.array(data)
    data_repeated = np.repeat(data, repetitions)

    unique, counts = np.unique(data_repeated, return_counts=True)
    modes = unique[counts == counts.max()]
    counts = counts[counts == counts.max()]

