import re
import socket
def task_func(ip_addresses: list) -> dict:
    # Regular expression to validate an IPv4 address
    ip_pattern = re.compile(r'^(\d{1,3}\.){3}\d{1,3}$')

    # Function to check if an IP is valid
    def is_valid_ip(ip):
        if ip_pattern.match(ip):
            parts = ip.split('.')
            return all(0 <= int(part) <= 255 for part in parts)
        return False

    # Initialize the result dictionary
    ip_to_hostname = {}

    # Iterate over the provided IP addresses
    for ip in ip_addresses:
        if is_valid_ip(ip):
            try:
                # Try to get the hostname for the IP address
                hostname = socket.gethostbyaddr(ip)[0]
            except (socket.herror, socket.gaierror):
                # If an error occurs, set the hostname to None
                hostname = None
            ip_to_hostname[ip] = hostname
        else:
            # If the IP is not valid, set the hostname to None
            ip_to_hostname[ip] = None

    return ip_to_hostname

