import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    # Load the JSON string into a Python dictionary
    data = json.loads(json_str)

    # Define a regex pattern for URLs
    url_pattern = re.compile(r'https?://[^\s]+')

    # Function to extract URLs from a given string
    def extract_urls(s):
        return url_pattern.findall(s)

    # Recursive function to traverse the dictionary and extract URLs
    def find_urls(obj):
        urls = []
        if isinstance(obj, dict):
            for key, value in obj.items():
                urls.extend(find_urls(value))
        elif isinstance(obj, list):
            for item in obj:
                urls.extend(find_urls(item))
        elif isinstance(obj, str):
            urls.extend(extract_urls(obj))
        return urls

    # Find all URLs in the JSON data
    all_urls = find_urls(data)

    # Count the occurrences of each URL
    url_counts = Counter(all_urls)

    # Return the top_n URLs as a dictionary
    return dict(url_counts.most_common(top_n))

