from datetime import datetime
def task_func(excel_directory: str, file_name: str, column_name: str, start_date: str, end_date: str) -> pd.DataFrame:
    # Construct the full file path
    file_path = os.path.join(excel_directory, file_name)

    # Check if the file exists
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The specified Excel file '{file_name}' does not exist in the directory '{excel_directory}'.")

    # Try to read the Excel file into a DataFrame
    try:
        df = pd.read_excel(file_path)
    except Exception as e:
        raise Exception(f"An error occurred while reading the Excel file: {e}")

    # Check if the column exists in the DataFrame
    if column_name not in df.columns:
        raise ValueError(f"The column '{column_name}' does not exist in the DataFrame.")

    # Try to parse the start_date and end_date
    try:
        start_date_parsed = datetime.strptime(start_date, '%Y-%m-%d')
        end_date_parsed = datetime.strptime(end_date, '%Y-%m-%d')
    except ValueError:
        raise ValueError("The start_date or end_date are in an incorrect format. Please use 'YYYY-MM-DD'.")

    # Ensure the column is of datetime type
    if not pd.api.types.is_datetime64_any_dtype(df[column_name]):
        try:
            df[column_name] = pd.to_datetime(df[column_name])
        except Exception as e:
            raise ValueError(f"Could not convert column '{column_name}' to datetime: {e}")

    # Filter the DataFrame based on the date range
    filtered_df = df[(df[column_name] >= start_date_parsed) & (df[column_name] <= end_date_parsed)]

    return filtered_df

import json
import re
import pandas as pd
def task_func(json_str):
    # Check if the input JSON string is empty
    if not json_str.strip():
        return pd.DataFrame()

    try:
        # Load JSON string into a dictionary
        data_dict = json.loads(json_str)
    except json.JSONDecodeError:
        # Return an empty DataFrame if JSON is invalid
        return pd.DataFrame()

    # Function to double numerical values
    def double_value(value):
        if isinstance(value, (int, float)):
            return value * 2
        elif isinstance(value, str):
            # Try to convert string to float and double it
            match = re.match(r'^-?\d+(\.\d+)?$', value)
            if match:
                return float(value) * 2
        elif isinstance(value, list):
            # Double each numerical value in the list
            return [double_value(item) for item in value]
        return value

    # Normalize the dictionary by doubling numerical values
    normalized_dict = {key: double_value(value) for key, value in data_dict.items()}

    # Create a DataFrame from the normalized dictionary
    df = pd.DataFrame([normalized_dict])

    return df

