            file_size = os.path.getsize(file_path)
            file_md5 = calculate_md5(file_path)
            result[normalized_name] = {'Size': file_size, 'MD5 Hash': file_md5}

    return result

import rsa
import urllib.request
from hashlib import sha256
from urllib.error import URLError, HTTPError
def task_func(url):
    try:
        # Generate RSA public and private keys
        (public_key, private_key) = rsa.newkeys(2048)

        # Retrieve content from the specified URL
        try:
            with urllib.request.urlopen(url) as response:
                content = response.read()
        except HTTPError as e:
            raise ValueError(f"HTTP error occurred: {e.code} {e.reason}")
        except URLError as e:
            raise URLError(f"URL error occurred: {e.reason}")
        except Exception as e:
            raise ValueError(f"An error occurred while reaching the server: {e}")

        # Calculate the SHA256 hash of the content
        content_hash = sha256(content).digest()

        # Sign the hash with the private key
        try:
            signed_hash = rsa.sign(content_hash, private_key, 'SHA-256')
        except rsa.pkcs1.VerificationError as e:
            raise rsa.pkcs1.VerificationError("Failed to sign the hash with the RSA private key")

        # Return the public key, the signed hash as a hexadecimal string, and the hashed content
        return public_key, signed_hash.hex(), content_hash

    except Exception as e:
        raise e

