import random
def task_func(df):
    """
    Adds a 'winner' column to the DataFrame based on the scores of the matches.
    If the scores are equal, the winner is randomly decided between the two teams.

    Parameters:
    df (pandas.DataFrame): The input DataFrame with columns 'team1', 'team2', 'score1', 'score2'.

    Returns:
    df (pandas.DataFrame): The DataFrame with the added 'winner' column.
    """
    def determine_winner(row):
        if row['score1'] > row['score2']:
            return row['team1']
        elif row['score2'] > row['score1']:
            return row['team2']
        else:
            return random.choice([row['team1'], row['team2']])

    df['winner'] = df.apply(determine_winner, axis=1)
    return df

