import os
import shutil
import tempfile
BACKUP_DIR = '/tmp/backup'
def get_unique_backup_dir():
    # Create a unique backup directory using tempfile
    return tempfile.mkdtemp(prefix='backup_', dir=BACKUP_DIR)
def task_func(directory):
    errors = []
    backup_dir = get_unique_backup_dir()

    try:
        # Ensure the backup directory exists
        os.makedirs(backup_dir, exist_ok=True)

        # Copy the directory to the backup location
        shutil.copytree(directory, backup_dir, dirs_exist_ok=True)

        # Clean the original directory
        for filename in os.listdir(directory):
            file_path = os.path.join(directory, filename)
            try:
                if os.path.isfile(file_path) or os.path.islink(file_path):
                    os.unlink(file_path)
                elif os.path.isdir(file_path):
                    shutil.rmtree(file_path)
            except Exception as e:
                errors.append(f"Error cleaning {file_path}: {str(e)}")
    except Exception as e:
        errors.append(f"Error during backup or cleanup: {str(e)}")

    return backup_dir, errors

