import os
import shutil
BACKUP_DIR = '/tmp/backup'
def task_func(directory):
    # Check if the backup directory exists
    if not os.path.exists(BACKUP_DIR):
        return f'Backup directory {BACKUP_DIR} does not exist. Cannot rollback update.'

    # Check if the directory to restore exists in the backup
    backup_path = os.path.join(BACKUP_DIR, os.path.basename(directory))
    if not os.path.exists(backup_path):
        return f'No backup found for directory {directory} in {BACKUP_DIR}. Cannot rollback update.'

    # Check if the target directory exists and remove it if it does
    if os.path.exists(directory):
        try:
            shutil.rmtree(directory)
        except Exception as e:
            return f'Failed to remove existing directory {directory}: {str(e)}'

    # Restore the directory from the backup
    try:
        shutil.copytree(backup_path, directory)
    except Exception as e:
        return f'Failed to restore directory {directory} from backup: {str(e)}'

    return directory

