def task_func(data, mapping):
    # Create a regex pattern to match whole words that are acronyms
    pattern = re.compile(r'\b(' + '|'.join(re.escape(key) for key in mapping.keys()) + r')\b')

    # Function to replace acronyms in a single string
    def replace_acronyms(text):
        if isinstance(text, str):
