import string
import random
def task_func(text, seed=None):
    if not text:
        raise ValueError("The input text is empty.")

    if seed is not None:
        random.seed(seed)

    def random_lower():
        return random.choice(string.ascii_lowercase)

    def random_digit():
        return random.choice(string.digits)

    def random_space():
        return random.choice(string.ascii_lowercase + string.digits)

    password = []

    for char in text:
        if char.isalpha():
            password.append(random_lower())
        elif char.isdigit():
            password.append(random_digit())
        elif char == ' ':
            password.append(random_space())
        else:
            password.append(char)

    return ''.join(password)

import os
from collections import Counter
def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    # Check if the directory exists
    if not os.path.exists(directory):
        raise OSError(f"The specified directory '{directory}' does not exist.")

    # Initialize a Counter object to store file counts
    file_counter = Counter({ext: 0 for ext in extensions} if keep_zero else {})

    # Walk through the directory recursively
    for root, _, files in os.walk(directory):
        for file in files:
            # Check if the file ends with any of the specified extensions
            for ext in extensions:
                if file.endswith(ext):
                    file_counter[ext] += 1

    return file_counter

