import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    # Validate JSON data
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("The JSON data is malformed.")

    if not isinstance(data, list):
        raise ValueError("The JSON data is malformed.")

    countries = []
    populations = []

    for item in data:
        if not isinstance(item, dict) or len(item) != 2:
            raise ValueError("The JSON data is malformed.")

        country = item.get("Country")
        population = item.get("Population")

        if not isinstance(country, str):
            raise ValueError("Country names must be strings.")

        if not isinstance(population, (int, float)) or population < 0:
            raise ValueError("Populations must be non-negative numbers.")

        countries.append(country)
        populations.append(math.floor(population))

    if not countries or not populations:
        raise ValueError("The JSON data is empty or invalid.")

    # Create DataFrame
    df = pd.DataFrame({
        "Country": countries,
        "Population": populations
    })

    # Write to CSV
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except IOError:
        raise IOError("The file cannot be written to the specified directory.")

    return file_path, df

import urllib.request
from lxml import etree
import pandas as pd
def task_func(url):
    try:
        # Fetch the XML file from the URL
        with urllib.request.urlopen(url) as response:
            xml_data = response.read()
    except Exception as e:
        raise ValueError("XML structure does not match expected format.") from e

    try:
        # Parse the XML data
        root = etree.fromstring(xml_data)
    except etree.XMLSyntaxError as e:
        raise ValueError("XML structure does not match expected format.") from e

    # Check if the root element contains 'item' elements
    if root.tag != 'items' or not list(root):
        raise ValueError("XML structure does not match expected format.")

    # Extract data from 'item' elements
    data = []
    for item in root:
        if item.tag != 'item':
            raise ValueError("XML structure does not match expected format.")
        item_data = {}
        for child in item:
            item_data[child.tag] = child.text
        data.append(item_data)

    # Convert the extracted data into a DataFrame
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise ValueError("XML structure does not match expected format.") from e

    return df

import urllib.request
import zipfile
import os
import urllib.error
import shutil
def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    try:
        # Download the file from the URL
        urllib.request.urlretrieve(url, save_path)
    except urllib.error.URLError as e:
        return f"URL Error: {e.reason}"
    except Exception as e:
        return f"Download Error: {str(e)}"

    try:
        # Ensure the extraction directory exists
        if not os.path.exists(extract_path):
            os.makedirs(extract_path)

        # Extract the ZIP file
        with zipfile.ZipFile(save_path, 'r') as zip_ref:
            zip_ref.extractall(extract_path)
    except zipfile.BadZipFile:
        return "File Error: The file is not a valid ZIP file."
    except Exception as e:
        return f"Extraction Error: {str(e)}"

    try:
        # Clean up by deleting the ZIP file
        os.remove(save_path)
    except Exception as e:
        return f"File Deletion Error: {str(e)}"

    return extract_path

