import pytesseract
from pytesseract import Output
import io
IMAGE_PATH = "image.png"
def task_func(filename=IMAGE_PATH, from_encoding="cp1251", to_encoding="utf8"):
    def ocr_extract_text(image):
        try:
            # Perform OCR to extract text from the image
            return pytesseract.image_to_string(image)
        except Exception as e:
            print(f"OCR extraction failed: {e}")
            return None

    def extract_comment(image):
        try:
            # Extract comments from the image metadata
            return image.info.get('comment', None)
        except Exception as e:
            print(f"Failed to extract comment: {e}")
            return None

    def convert_encoding(text, from_enc, to_enc):
        try:
            # Convert text from one encoding to another
            return text.encode(from_enc).decode(to_enc)
        except (UnicodeDecodeError, LookupError) as e:
            raise ValueError(f"Encoding conversion failed: {e}")

    try:
        with Image.open(filename) as img:
            # Attempt to extract text using OCR
            ocr_text = ocr_extract_text(img)
            if ocr_text:
                return convert_encoding(ocr_text, from_encoding, to_encoding)

            # Attempt to extract and convert text from image comments
            comment = extract_comment(img)
            if comment:
                return convert_encoding(comment, from_encoding, to_encoding)

    except Exception as e:
        print(f"An error occurred: {e}")

    # Return an empty string if both OCR and comment extraction fail
    return ""

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    try:
        # Initiate an HTTP GET request with a 5-second timeout
        response = requests.get(url, timeout=5)
        response.raise_for_status()  # Raise an error for bad responses
        content = response.content  # Get the response content in raw bytes

        # Handle empty content
        if not content:
            return {}

        # Detect encoding if not provided
        if not from_encoding:
            detected_encoding = chardet.detect(content)['encoding']
            if not detected_encoding:
                raise ValueError("Unable to detect encoding for non-empty content")
            from_encoding = detected_encoding

        # Decode the content using the detected or provided encoding
        decoded_content = content.decode(from_encoding)

        # Re-encode the content to the target encoding
        re_encoded_content = decoded_content.encode(to_encoding).decode(to_encoding)

        # Parse the JSON data
        json_data = json.loads(re_encoded_content)
        return json_data

    except requests.exceptions.RequestException as e:
        print(f"HTTP Request failed: {e}")
        return {}
    except json.JSONDecodeError as e:
        print(f"JSON decoding failed: {e}")
        return {}
    except ValueError as e:
        raise e

