def get_cpu_usage():
    system = platform.system()
    if system == "Windows":
        return get_cpu_usage_windows()
    elif system in ("Linux", "Darwin"):
        return get_cpu_usage_unix()
    else:
        raise OSError(f"Unsupported operating system: {system}")
def get_cpu_usage_windows():
    try:
        # Using WMIC command to get CPU load percentage
        result = subprocess.run(['wmic', 'cpu', 'get', 'loadpercentage'], capture_output=True, text=True, check=True)
        # Parsing the output to get the CPU load percentage
        cpu_load = result.stdout.strip().split('\n')[-1].strip()
        return int(cpu_load)
    except Exception as e:
        raise RuntimeError("Failed to retrieve CPU usage on Windows.") from e
def get_cpu_usage_unix():
    try:
        # Using top command to get CPU usage
        result = subprocess.run(['top', '-bn1'], capture_output=True, text=True, check=True)
        # Parsing the output to get the CPU usage percentage
        for line in result.stdout.split('\n'):
            if 'Cpu(s)' in line:
                cpu_load = line.split(',')[0].split(':')[1].strip().split()[0]
                return float(cpu_load)
        raise RuntimeError("Failed to parse CPU usage from top command output.")
    except Exception as e:
        raise RuntimeError("Failed to retrieve CPU usage on Unix/Linux.") from e

