import difflib
import gzip
def task_func(file_path1, file_path2):
    with gzip.open(file_path1, 'rb') as f1, gzip.open(file_path2, 'rb') as f2:
        file1_contents = f1.read()
        file2_contents = f2.read()

    diff = difflib.ndiff(file1_contents, file2_contents)
    differences = [line for line in diff if line.startswith('+') or line.startswith('-')]

    if not differences:
        return ''
    else:
        return '\n'.join(differences)

import os
import sys
import importlib
from pkgutil import iter_modules
def task_func(package_name):
    """
    Adds all modules of a specified package to the system path.
    This function is useful for dynamically importing modules from a package that might not be on the standard path.
    """
    try:
        package = importlib.import_module(package_name)
    except ImportError:
        raise ImportError(f"Package '{package_name}' not found. Please install it by running 'pip install {package_name}'")

    module_names = []
    for module in iter_modules(package.__path__):
        module_name = module.name
        if module_name not in sys.modules:
            sys.modules[module_name] = importlib.import_module(module_name)
            module_names.append(module_name)

    return module_names

