import shutil
BACKUP_DIR = '/tmp/backup'
def task_func(directory):
    # Check if the backup directory exists
    if not os.path.exists(BACKUP_DIR):
        return 'Backup directory {} does not exist. Cannot rollback update.'.format(BACKUP_DIR)

    # Check if the directory to be rolled back exists
    if not os.path.exists(directory):
        return 'Directory {} does not exist. Cannot rollback update.'.format(directory)

    # Get the backup file for the directory
    backup_file = os.path.join(BACKUP_DIR, os.path.basename(directory))

    # Check if the backup file exists
    if not os.path.exists(backup_file):
        return 'Backup file {} does not exist. Cannot rollback update.'.format(backup_file)

    # Restore the directory from the backup file
    shutil.copytree(backup_file, directory)

    return directory

