import requests
from pathlib import Path
import zipfile
import os
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    """
    Downloads and extracts a zip file from a specified URL.
    :param url: The URL of the zip file to download.
    :param filename: The name of the zip file.
    :return: A tuple containing a status message and a list of filenames in the unzipped directory, or an empty list if extraction fails.
    """
    # Create the download directory if it doesn't exist
    if not DOWNLOAD_DIR.exists():
        DOWNLOAD_DIR.mkdir()

    # Create the unzipped directory if it doesn't exist
    if not ZIP_DIR.exists():
        ZIP_DIR.mkdir()

    # Download the zip file
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        return ("Error: Network-related exception occurred while downloading the zip file.", [])
    except Exception as e:
        return ("Error: Unknown exception occurred while downloading the zip file.", [])

    # Save the zip file to the download directory
    zip_file_path = DOWNLOAD_DIR / filename
    with open(zip_file_path, "wb") as f:
        f.write(response.content)

    # Extract the zip file
    try:
        with zipfile.ZipFile(zip_file_path, "r") as zip_ref:
            zip_ref.extractall(ZIP_DIR)
    except zipfile.BadZipFile as e:
        return ("Error: The zip file is corrupted or invalid.", [])
    except Exception as e:
        return ("Error: Unknown exception occurred while extracting the zip file.", [])

    # Get the list of filenames in the unzipped directory
    filenames = [f.name for f in os.scandir(ZIP_DIR) if f.is_file()]

    # Return the status message and the list of filenames
    return ("Success: The zip file was downloaded and extracted successfully.", filenames)

