import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder and move the compressed files to a destination folder.
    This operation is executed as a background process using the 'gzip' command.
    The function should output with:
        dict: A dictionary containing:
        'success': A boolean indicating if all files were compressed and moved successfully.
        'message': A descriptive message about the operation's result.
        'failed_files': A list of filenames that failed to compress or move.
    """
    # Check if the source folder exists
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': f"Source folder '{src_folder}' does not exist."}

    # Check if the destination folder exists
    if not os.path.isdir(dst_folder):
        return {'success': False, 'message': f"Destination folder '{dst_folder}' does not exist."}

    # Get a list of all files in the source folder
    files = glob(os.path.join(src_folder, '*'))

    # Create a list to store the failed files
    failed_files = []

    # Iterate over the files and compress them
    for file in files:
        # Check if the file is a file
        if os.path.isfile(file):
            # Compress the file using gzip
            subprocess.run(['gzip', file], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

            # Move the compressed file to the destination folder
            shutil.move(file + '.gz', dst_folder)

            # Check if the file was moved successfully
            if not os.path.isfile(os.path.join(dst_folder, file + '.gz')):
                failed_files.append(file)

    # Check if all files were compressed and moved successfully
    if len(failed_files) == 0:
        return {'success': True, 'message': f"All files in '{src_folder}' were compressed and moved to '{dst_folder}'."}
    else:
        return {'success': False, 'message': f"Failed to compress and move the following files: {', '.join(failed_files)}."}

