import string
def task_func(length: int, predicates: list, seed: int = None):
    """
    Generates a random string of specified length and evaluates it for specific characteristics.
    Notes:
        - Predicates are deduplicated.
        - Characters are randomly sampled from string.ascii_letters, string.digits, and string.punctuation with replacement.
        - Any invalid predicates provided will result in a KeyError.
        - If no predicates are provided, the result dictionary will be empty.
    The function should raise the exception for:
        - ValueError: If the specified length is negative.
        - KeyError: If any predicate is not recognized.
    The function should output with:
        - tuple:
            - string: the generated random text
            - dict: the text's characteristics
    """
    if length < 0:
        raise ValueError("Length must be non-negative")

    if seed is not None:
        random.seed(seed)

    predicates = set(predicates)
    if not predicates:
        return "", {}

    text = "".join(random.choice(string.ascii_letters + string.digits + string.punctuation) for _ in range(length))

    characteristics = {}
    for predicate in predicates:
        if predicate == "has_lowercase":
            characteristics[predicate] = any(c.islower() for c in text)
        elif predicate == "has_uppercase":
            characteristics[predicate] = any(c.isupper() for c in text)
        elif predicate == "has_digits":
            characteristics[predicate] = any(c.isdigit() for c in text)
        elif predicate == "has_punctuation":
            characteristics[predicate] = any(c in string.punctuation for c in text)
        else:
            raise KeyError(f"Invalid predicate: {predicate}")

    return text, characteristics

