import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse
def task_func(data):
    # Define the correct username and password
    correct_username = 'admin'
    correct_password_hash = base64.b64encode(hashlib.sha256('password'.encode()).digest()).decode()

    # Check if the required keys are present in the input data
    if 'username' not in data or 'password' not in data:
        return HttpResponseBadRequest('Bad Request.')

    # Extract the username and password from the input data
    username = data['username']
    password = data['password']

    # Decode the base64-encoded password
    try:
        decoded_password = base64.b64decode(password)
    except binascii.Error:
        return HttpResponseBadRequest('Bad Request.')

    # Calculate the SHA-256 hash of the decoded password
    password_hash = base64.b64encode(hashlib.sha256(decoded_password).digest()).decode()

    # Compare the calculated hash with the correct hash
    if username == correct_username and password_hash == correct_password_hash:
        return HttpResponse('Login successful.', status=400)
    else:
        return HttpResponse('Login failed.', status=401)

