                    return True
            # If the value is a string and matches the search string, return True
            elif isinstance(value, str) and value == string:
                return True
    # Check if the current data is a list
    elif isinstance(data, list):
        # Iterate through each item in the list
        for item in data:
            # If the item is a dictionary or a list, recursively search
            if isinstance(item, (dict, list)):
                if search_in_json(item, string):
                    return True
    # If no match is found, return False
