import json
from datetime import datetime
from decimal import Decimal
def task_func(my_obj):
    # Custom JSON encoder to handle datetime and Decimal types
    class CustomEncoder(json.JSONEncoder):
        def default(self, obj):
            if isinstance(obj, datetime):
                # Serialize datetime objects to ISO format
                return obj.isoformat()
            elif isinstance(obj, Decimal):
                # Serialize Decimal objects to string
                return str(obj)
            # Let the base class default method raise the TypeError
            return json.JSONEncoder.default(self, obj)

    # Serialize the object using the custom encoder
    return json.dumps(my_obj, cls=CustomEncoder)

import json
from datetime import datetime
import numpy as np
from decimal import Decimal
class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        elif isinstance(obj, np.ndarray):
            return obj.tolist()
        elif isinstance(obj, Decimal):
            return str(obj)
        else:
            return super().default(obj)
def task_func(my_obj):
    try:
        return json.dumps(my_obj, cls=CustomJSONEncoder)
    except TypeError as e:
        raise TypeError("Unsupported type encountered during serialization") from e

