import os
import pathlib
from hashlib import md5
import unicodedata
def normalize_filename(filename):
    # Normalize the filename to ASCII
    return unicodedata.normalize('NFKD', filename).encode('ascii', 'ignore').decode('ascii')
def calculate_md5_hash(file_path):
    # Calculate the MD5 hash of the file
    hash_md5 = md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()
def task_func(directory):
    # Initialize the result dictionary
    result = {}

    # Iterate over all files in the specified directory
    for file_path in pathlib.Path(directory).iterdir():
        if file_path.is_file():
            # Normalize the filename
            normalized_name = normalize_filename(file_path.name)

            # Calculate the MD5 hash and size of the file
            file_size = file_path.stat().st_size
            file_hash = calculate_md5_hash(file_path)

            # Add the file's size and hash to the result dictionary
            result[normalized_name] = {'Size': file_size, 'MD5 Hash': file_hash}

    # Return the result dictionary
    return result

