import numpy as np
def task_func(fruit_data):
    if not fruit_data:
        return pd.DataFrame(columns=['Total Count', 'Average Count'])

    # Create a dictionary to store total and average counts for each fruit
    fruit_counts = {}

    for fruit, count in fruit_data:
        if fruit in fruit_counts:
            fruit_counts[fruit]['Total Count'] += count
            fruit_counts[fruit]['Average Count'] = fruit_counts[fruit]['Total Count'] / len(fruit_counts[fruit]['Counts'])
            fruit_counts[fruit]['Counts'].append(count)
        else:
            fruit_counts[fruit] = {'Total Count': count, 'Average Count': count, 'Counts': [count]}

    # Convert the dictionary to a pandas DataFrame
    df = pd.DataFrame.from_dict(fruit_counts, orient='index')

    return df[['Total Count', 'Average Count']]

