import re
from datetime import datetime, timedelta
def task_func(logs: list):
    error_times = []
    total_time = timedelta(0)

    for log in logs:
        match = re.search(r'\d{2}:\d{2}:\d{2}', log)
        if match:
            error_time_str = match.group()
            error_time = datetime.strptime(error_time_str, '%H:%M:%S').time()
            error_times.append(error_time)
            total_time += timedelta(hours=error_time.hour, minutes=error_time.minute, seconds=error_time.second)

    if error_times:
        average_time = total_time / len(error_times)
    else:
        average_time = None

    return {'list': error_times, 'time': average_time}

