import os
import glob
from collections import Counter
def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    # Check if the specified directory exists
    if not os.path.exists(directory):
        raise OSError("The specified directory does not exist.")

    # Initialize a Counter object to store file counts
    file_counter = Counter()

    # Traverse the directory recursively
    for ext in extensions:
        # Use glob to find files with the specified extension
        for file_path in glob.glob(os.path.join(directory, "**", "*" + ext), recursive=True):
            # Increment the count for the file extension
            file_counter[ext] += 1

    # If keep_zero is False, remove extensions with zero counts
    if not keep_zero:
        file_counter = {ext: count for ext, count in file_counter.items() if count > 0}

    # Return the Counter object containing file counts
    return file_counter

import os
import re
from pathlib import Path
def task_func(dir_path: str, predicates: list) -> dict:
    # Check if no valid predicates are provided
    if not predicates:
        raise ValueError("No valid predicates provided")

    # Check if the specified directory exists and is a directory
    if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
        raise FileNotFoundError("The specified directory does not exist or is not a directory")

    # Initialize the result dictionary
    result = {}

    # Iterate over each item in the directory
    for item in os.listdir(dir_path):
        # Check each predicate against the item name
        for predicate in predicates:
            # If the predicate is a string, check if the item name contains the string
            if isinstance(predicate, str):
                if predicate in item:
                    result[item] = True
                    break
            # If the predicate is a regular expression, check if the item name matches the regex
            elif isinstance(predicate, re.Pattern):
                if predicate.search(item):
                    result[item] = True
                    break
        # If no predicates match, set the result to False
        else:
            result[item] = False

    return result

