        elif predicate == 'isalnum':
            characteristics['isalnum'] = random_string.isalnum()
        elif predicate == 'isspace':
            characteristics['isspace'] = random_string.isspace()
        elif predicate == 'istitle':
            characteristics['istitle'] = random_string.istitle()
        elif predicate == 'islower':
            characteristics['islower'] = random_string.islower()
        elif predicate == 'isupper':
            characteristics['isupper'] = random_string.isupper()
        elif predicate == 'isprintable':
            characteristics['isprintable'] = random_string.isprintable()
        elif predicate == 'isdecimal':
            characteristics['isdecimal'] = random_string.isdecimal()
        elif predicate == 'isnumeric':
