import pytesseract
IMAGE_PATH = "image.png"
def task_func(filename=IMAGE_PATH, from_encoding="cp1251", to_encoding="utf8"):
    try:
        # Attempt OCR extraction
        image = Image.open(filename)
        text = pytesseract.image_to_string(image)
        if text:
            return text.encode(from_encoding).decode(to_encoding)
    except Exception as e:
        # Handle OCR extraction errors
        print(f"OCR extraction failed: {e}")

    try:
        # Attempt comment processing
        with open(filename, 'rb') as f:
            comment = f.read().decode(from_encoding)
            if comment:
                return comment.encode(from_encoding).decode(to_encoding)
    except (UnicodeDecodeError, LookupError) as e:
        # Handle comment processing errors
        raise ValueError(f"Encoding error during comment processing: {e}")
    except Exception as e:
        # Handle other comment processing errors
        print(f"Comment processing failed: {e}")

    # Return an empty string if both OCR extraction and comment processing fail
    return ""

