from sklearn.preprocessing import LabelEncoder
def task_func(df, dct, columns=None):
    """
    Preprocesses a pandas DataFrame by replacing specified values, encoding categorical attributes, and standardizing numerical attributes.

    Args:
        df (pd.DataFrame): The DataFrame to be preprocessed.
        dct (dict): A dictionary with keys as column names and values as lists of values to be replaced.
        columns (list): A list of column names to be preprocessed. If None, all columns will be preprocessed.

    Returns:
        pd.DataFrame: The preprocessed DataFrame with encoded categorical attributes and standardized numerical attributes.
    """
    if not isinstance(df, pd.DataFrame):
        raise ValueError("Input df must be a pandas DataFrame.")

    if columns is None:
        columns = df.columns

    # Replace specified values
    for col, values in dct.items():
        if col in columns:
            df[col] = df[col].replace(values)

    # Encode categorical attributes
    for col in columns:
        if df[col].dtype == object:
            le = LabelEncoder()
            df[col] = le.fit_transform(df[col])

    # Standardize numerical attributes
    for col in columns:
        if df[col].dtype in ['int64', 'float64']:
            df[col] = (df[col] - df[col].mean()) / df[col].std()

    return df
