import os
import glob
from collections import Counter
def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    """
    Traverses a given directory recursively to count files by specified extensions.
    Note that: This function counts files in a case-sensitive manner.
    The function should raise the exception for: OSError: If the specified directory does not exist.
    The function should output with:
        Counter: An object containing counts of files for each of the specified extensions.
    """
    if not os.path.isdir(directory):
        raise OSError("The specified directory does not exist.")

    file_counts = Counter()
    for ext in extensions:
        file_counts[ext] = 0

    for root, dirs, files in os.walk(directory):
        for file in files:
            for ext in extensions:
                if file.endswith(ext):
                    file_counts[ext] += 1

    if not keep_zero:
        file_counts = {k: v for k, v in file_counts.items() if v > 0}

    return file_counts

import os
import shutil
def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path:
        raise ValueError("Path must be a non-empty string.")
    if not os.path.exists(path):
        raise FileNotFoundError("Path does not exist.")

    path_components = path.split(delimiter)
    if not all(path_components):
        raise ValueError("Path contains invalid components.")

    disk_usage = []
    for i, component in enumerate(path_components):
        component_path = delimiter.join(path_components[:i+1])
        total, used, free = shutil.disk_usage(component_path)
        disk_usage.append((component, {
            "total": total,
            "used": used,
            "free": free
        }))

    return disk_usage

