import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"File {script_path} does not exist.")

    def run_script():
        subprocess.run(["python", script_path])

    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout)

    if thread.is_alive():
        return "Terminating process due to timeout."
    else:
        return "Script executed successfully."

import re
import json
import requests
def task_func(myString, token):
    # Extract the URL from the string
    url = re.search(r'https?://\S+', myString)
    if url:
        url = url.group(0)
    else:
        return None

    # Prepare the request
    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json'
    }
    payload = {
        'url': url
    }

    # Send the request
    response = requests.post('https://example.com/api/endpoint', headers=headers, data=json.dumps(payload))

    # Return the response
    return response.json()
